;EACA,yBAAA;MAAA,sBAAA;UAAA,mBAAA;EACA,kBAAA;EACA,WAAA;AC/LV;AD7pBA;EA+1BY,gBAAA;EACA,cAAA;AC/LZ;ADjqBA;EAq2BU,oBAAA;EAAA,oBAAA;EAAA,aAAA;EACA,mBAAA;MAAA,WAAA;UAAA,OAAA;ACjMV;ADrqBA;EAy2BY,mBAAA;MAAA,WAAA;UAAA,OAAA;EACA,kBAAA;EACA,YAAA;EACA,WAAA;ACjMZ;ADmMY;EACE,cAAA;EACA,iBAAA;ACjMd;AD/qBA;EAu3BQ,WAAA;EACA,kBAAA;EACA,gBAAA;ACrMR;ADprBA;EA43BU,cAAA;EACA,WAAA;EACA,gBAAA;EACA,oBAAA;KAAA,iBAAA;ACrMV;AD1rBA;EAo4BQ,YAAA;ACvMR;ADyMQ;EAEI,WAAA;ACxMZ;AD4MQ;EAEI,WAAA;EACA,oBAAA;EAAA,oBAAA;EAAA,aAAA;EACA,kBAAA;EACA,YAAA;EACA,gBAAA;AC3MZ;ADqMQ;EASM,WAAA;EACA,YAAA;EACA,iBAAA;AC3Md;ADgMQ;EAeM,mBAAA;MAAA,WAAA;UAAA,OAAA;AC5Md;ADiNQ;EAEI,UAAA;AChNZ;ADoNQ;EAEI,gBAAA;ACnNZ;ADrtBA;EA66BU,YAAA;ACrNV;ADxtBA;EAg7BY,kBAAA;EACA,WAAA;EACA,SAAA;EACA,oBAAA;EACA,gBAAA;EACA,mBAAA;ACrNZ;ADhuBA;EAw7Bc,kBAAA;EACA,WAAA;EACA,YAAA;EACA,6DAAA;ACrNd;ADtuBA;EAg8BY,YAAA;EACA,gBAAA;ACvNZ;AD1uBA;EAo8Bc,eAAA;EACA,cAAA;EACA,YAAA;EACA,gBAAA;EACA,gBAAA;EACA,kBAAA;ACvNd;ADlvBA;EA68Bc,eAAA;EACA,iBAAA;ACxNd;ADtvBA;EAi9BgB,eAAA;EACA,iBAAA;ACxNhB;AD1vBA;EA69BI,kBAAA;AChOJ;ADkOI;EACE,WAAA;AChON;ADmOI;EACE,WAAA;ACjON;ADoOI;EACE,0BAAA;AClON;ADqOI;;EAEE,kBAAA;EACA,MAAA;EACA,OAAA;EACA,QAAA;EACA,SAAA;EACA,0BAAA;EACA,YAAA;ACnON","sourcesContent":["ol,\nul,\ndl {\n  margin: 0;\n  padding: 0;\n}\n\n// diy手机\n.phone-content {\n  width: 377px;\n  margin-top: 25px;\n  border-radius: 3px;\n  box-shadow: 0 0 28px 0 #ccc;\n  border: 1px solid #ddd;\n  background: #fff;\n\n  .phone-top {\n    width: 100%;\n    height: 66px;\n    text-align: center;\n    background-position: center;\n    background-size: contain;\n    background-repeat: no-repeat;\n\n    &.black {\n      background-image: url('~@/assets/img/phone-top-black.png');\n    }\n\n    &.white {\n      background-image: url('~@/assets/img/phone-top-white.png');\n    }\n\n    .title {\n      margin: 0;\n      font-size: 14px;\n      font-weight: normal;\n      white-space: nowrap;\n      line-height: 88px;\n    }\n  }\n\n  // diy元素容器\n  .phone-main {\n    position: relative;\n    border-top: 0;\n    user-select: none;\n    line-height: normal;\n\n    .content {\n      overflow-y: auto;\n      height: 580px;\n    }\n\n    .devise-item {\n      display: block;\n      overflow: hidden;\n      font-size: 13px;\n\n      .btn-edit-del {\n        height: 16px;\n        position: absolute;\n        right: 2px;\n        bottom: 2px;\n        display: none;\n        z-index: 90;\n\n        &>div {\n          width: 32px;\n          height: 16px;\n          line-height: 16px;\n          display: inline-block;\n          text-align: center;\n          font-size: 10px;\n          color: #fff;\n          background: rgba(0, 0, 0, 0.4);\n          margin-left: 2px;\n          cursor: pointer;\n          position: relative;\n          z-index: 11;\n        }\n      }\n\n      // 选中状态\n      &.selected,\n      &:hover {\n\n        // 显示删除按钮\n        .btn-edit-del {\n          display: block;\n        }\n      }\n    }\n\n    a {\n      color: #337ab7;\n    }\n\n    // diy-搜索\n    .diy-search {\n      background: #f1f1f2;\n      padding: 10px 10px;\n\n      .inner {\n        height: 30px;\n        background: #fff;\n        overflow: hidden;\n\n        &.radius {\n          border-radius: 5px;\n        }\n\n        &.round {\n          border-radius: 30px;\n        }\n\n        .search-input {\n          height: 30px;\n          //width: 100%;\n          line-height: 30px;\n          color: #999999;\n          padding: 0 10px;\n          font-size: 13px;\n\n          .search-icon {\n            margin-right: 4px;\n          }\n        }\n      }\n    }\n\n    // diy-banner\n    .diy-banner {\n      display: block;\n      margin: 0;\n      padding: 0;\n      height: auto;\n      overflow: hidden;\n\n      //position: relative;\n      img {\n        display: none;\n        width: 100%;\n\n        &:first-child {\n          display: block;\n        }\n      }\n\n      .dots {\n        height: 14px;\n        padding: 0 10px;\n        position: absolute;\n        left: 0;\n        right: 0;\n        bottom: 10px;\n        opacity: 0.8;\n        display: flex;\n        justify-content: center;\n\n\n        &-item {\n          margin-right: 3px;\n          height: 10px;\n          width: 10px;\n\n          &:last-child {\n            margin-right: 0;\n          }\n        }\n\n        &.rectangle {\n          .dots-item {\n            width: 16px;\n          }\n        }\n\n        &.square {\n          .dots-item {\n            width: 10px;\n          }\n        }\n\n        &.round {\n          .dots-item {\n            height: 10px;\n            width: 10px;\n            border-radius: 10px;\n          }\n        }\n      }\n    }\n\n    // diy-图片组\n    .diy-image {\n      display: block;\n      margin: 0;\n      padding: 0;\n      height: auto;\n      overflow: hidden;\n\n      img {\n        display: block;\n        width: 100%;\n      }\n    }\n\n    // diy-按钮组\n    .diy-navBar {\n      .item-nav {\n        float: left;\n        margin: 10px 0;\n        text-align: center;\n\n        .item-image {\n          text-align: center;\n          margin-bottom: 4px;\n\n          img {\n            height: 44px;\n            width: 44px;\n          }\n        }\n\n      }\n\n      /* 分列布局 */\n      .avg-sm-3>.item-nav {\n        width: 33.33333333%;\n      }\n\n      .avg-sm-4>.item-nav {\n        width: 25%;\n      }\n\n      .avg-sm-5>.item-nav {\n        width: 20%;\n      }\n\n    }\n\n    // diy-辅助线\n    .diy-guide {\n      .line {\n        height: 0;\n        width: 100%;\n      }\n    }\n\n    // diy-视频组\n    .diy-video {\n      video {\n        display: block;\n        width: 100%;\n        height: 100%;\n      }\n    }\n\n    // diy-文章组\n    .diy-article {\n      background: #f7f7f7;\n\n      .article-item {\n        margin-bottom: 10px;\n        padding: 15px;\n        background: #fff;\n\n        &:last-child {\n          margin-bottom: 0;\n        }\n\n        .article-title {\n          font-size: 13px;\n          color: #333;\n        }\n\n        &__image image {\n          display: block;\n        }\n\n        &__footer {\n          margin-top: 5px;\n\n          .article-views {\n            font-size: 12px;\n            color: #888;\n          }\n        }\n\n        // 小图模式\n        &.show-type__10 {\n          display: flex;\n\n          .article-item__left {\n            padding-right: 10px;\n          }\n\n          .article-item__title {\n            min-height: 36px;\n          }\n\n          .article-item__image img {\n            display: block;\n            width: 120px;\n          }\n        }\n\n        // 大图模式\n        &.show-type__20 {\n          .article-item__image {\n            margin-top: 12.5px;\n\n            img {\n              display: block;\n              width: 100%;\n            }\n          }\n        }\n      }\n    }\n\n    // diy-专题组\n    .diy-special {\n      line-height: normal;\n\n      .special-left {\n        padding: 5px 10px;\n\n        img {\n          display: block;\n          width: 70px;\n        }\n      }\n\n      .special-content {\n        //width: 250px;\n        overflow: hidden;\n\n        .content-item {\n          padding: 2px 0;\n          font-size: 13px;\n          color: #141414;\n        }\n\n        &.display_1 {\n          height: 22px;\n        }\n\n        &.display_2 {\n          height: 44px;\n        }\n      }\n\n      .special-more {\n        padding: 12px 10px;\n        font-size: 12px;\n      }\n    }\n\n    // diy-图片橱窗\n    .diy-window {\n\n      .item-image img {\n        display: block;\n        width: 100%;\n      }\n\n      .data-item {\n        float: left;\n      }\n\n      /* 分列布局 */\n      .avg-sm-2>.data-item {\n        width: 50%;\n      }\n\n      .avg-sm-3>.data-item {\n        width: 33.33333333%;\n      }\n\n      .avg-sm-4>.data-item {\n        width: 25%;\n      }\n\n      .avg-sm-5>.data-item {\n        width: 20%;\n      }\n\n      // 橱窗样式\n      .display {\n        height: 0;\n    