<script>
import Vue from 'vue'
import vcolorpicker from 'vcolorpicker'
import PropTypes from 'ant-design-vue/es/_util/vue-types'
import draggable from 'vuedraggable'
import { Ueditor } from '@/components'
import { SImage, SArticleCate, SGoods, SVoucher, SGoodsCate, SLink } from './modules'
import ChannelEnum from '@/common/enum/file/Channel'
import * as CatApi from '@/api/category'
import { linkList } from '@/common/model/Links'

Vue.use(vcolorpicker)

export default {
  props: {
    // 页面装修默认数据
    defaultData: PropTypes.object.def({}),
    // 页面数据
    data: PropTypes.object.def({}),
    // 当前选中的元素
    curItem: PropTypes.object.def({}),
    // 当前选中的元素索引
    selectedIndex: PropTypes.oneOfType([PropTypes.number, PropTypes.string]).def(0),
    pageId: PropTypes.integer.def(0),
  },
  components: {
    draggable,
    Ueditor,
    SImage,
    SArticleCate,
    SGoods,
    SGoodsCate,
    SLink,
    SVoucher,
  },
  data () {
    return {
      channel: ChannelEnum.PAGE.value,
      loadCategory: false,
      categoryIdToLoad: 0,
      navItemToLoadCat: null,
      goodsTypes: [
        {label: '实物商品', value: 'physical'},
        {label: '虚拟商品', value: 'virtual'},
        {label: '旅游商品', value: 'travel'},
        {label: '核销商品', value: 'verification'},
        {label: '同城配送', value: 'intra-city'},
      ],
    }
  },
  watch: {
    'curItem.data': function() {
      if (/^(goods|article)$/.test(this.curItem.type) && this.curItem.data && this.curItem.data.length) {
        this.curItem.params.choice.ids = this.curItem.data.map(d => d.id);
        this.curItem.params.choice.sku_ids = this.curItem.data.filter(d => d.sku_id).map(d => d.sku_id);
      }
    }
  },
  methods: {

    // 新增数据
    handleAddData (max = 1) {
      const { defaultData, curItem } = this
      const newDataItem = defaultData.items[curItem.type].data[0]
      curItem.data.push(_.cloneDeep(newDataItem))
    },

    /**
     * 编辑器：删除data元素
     * @param curItem
     * @param index
     */
    handleDeleleData (curItem, index) {
      if (curItem.data.length <= 1) {
        this.$message.warning('至少保留一个')
        return false
      }
      curItem.data.splice(index, 1)
    },

    /**
     * 重置颜色
     * @param holder
     * @param attribute
     * @param color
     */
    onEditorResetColor (holder, attribute, color) {
      holder[attribute] = color
    },

    /* 加载分类到导航 */
    async handleLoadCategory () {
      if (!this.categoryIdToLoad) return this.loadCategory = false;
      const res = await CatApi.get(this.categoryIdToLoad)
      this.navItemToLoadCat.text = res.name
      this.navItemToLoadCat.imgUrl = res.image_url || res.image && res.image.external_url
      const linkDefault = linkList.filter(l => l.key=='store')[0].data.filter(d => d.id=='995bf1c')[0]
      this.navItemToLoadCat.link = {
        ...linkDefault,
        param: {
          path: "pages/tabBar/category/category",
          query: {
            category_id: this.categoryIdToLoad,
            category_name: res.name,
            category_imgUrl: this.navItemToLoadCat.imgUrl,
          },
          url: "pages/tabBar/category/category?category_id=" + this.categoryIdToLoad,
        }
      }
      this.navItemToLoadCat.link.form.filter(f => f.key=='query.category_id')[0].value = this.categoryIdToLoad
      this.loadCategory = false
    },

  }
}
</script>
